import{_ as e,o as t,c as r,a2 as i}from"./chunks/framework.BW2T23B9.js";const _=JSON.parse('{"title":"AI 伴学","description":"","frontmatter":{},"headers":[],"relativePath":"guide/ai.md","filePath":"guide/ai.md","lastUpdated":null}'),l={name:"guide/ai.md"};function o(n,a,s,d,h,u){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="ai-伴学" tabindex="-1">AI 伴学 <a class="header-anchor" href="#ai-伴学" aria-label="Permalink to &quot;AI 伴学&quot;">​</a></h1><p>AI 跟的是你正在学的句子、语法和错题，不是通用聊天窗口。没有配置模型时，Turna 仍可用本地课程片段做讲解；关掉 AI 也不影响学习和复习。</p><p>产品页演示见 <a href="./../../ai.html">ai.html</a>。</p><h2 id="能做什么" tabindex="-1">能做什么 <a class="header-anchor" href="#能做什么" aria-label="Permalink to &quot;能做什么&quot;">​</a></h2><ul><li><strong>跟课答疑</strong>：问正在学的那句、那个词缀，而不是「随便聊聊土耳其语」。</li><li><strong>先提示，后揭晓</strong>：从概念到规则再到完整讲解，避免一次把答案倒完。</li><li><strong>按错题和弱词练</strong>：用最近的错题、记得不稳的词生成一次短练习。</li><li><strong>情景对话</strong>：在 A1–B1 场景里开口，结束有复盘。</li></ul><h2 id="和复习的关系" tabindex="-1">和复习的关系 <a class="header-anchor" href="#和复习的关系" aria-label="Permalink to &quot;和复习的关系&quot;">​</a></h2><p>弱词、错题来自 FSRS 与课程记录。AI 只是读取这些本地数据来出题或解释，不把学习记录上传到「必须在线才能学」的后端。未配置密钥时走本地片段，有密钥时走统一 AI 引擎层（流式、可取消、可缓存）。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/docs/guide/fsrs">FSRS 复习</a></li><li><a href="/docs/guide/curriculum">课程结构</a></li></ul>',9)])])}const p=e(l,[["render",o]]);export{_ as __pageData,p as default};
